"""Detailed explanations with diagrams: HLD questions, part 2."""
from sd_x_util import X, P, H, AN, KEY, FLOW, SEQ, NOTE, ER, TABLE, CALC, BARS, CODE, UML, STATE

X("instagram-hld",
  P("""**What the system does.** Users upload photos and videos, follow others, and scroll a feed. Two loads dominate: **media bytes** (hundreds of terabytes a day) and **feed reads** (100k+ per second). The key ideas: keep heavy bytes **off your servers** (upload straight to object storage, serve through a CDN) and reuse the news-feed design for the timeline."""),
  AN("A photo lab: customers drop film directly into a secure mailbox (pre-signed upload to S3); technicians develop prints in several sizes (processing workers); shops around the city keep copies of popular prints so customers don't travel to the lab (CDN)."),
  CALC("Sizing", [("Uploads per second", "u = 100e6 / 86400", "/s"), ("New media per day (2 MB, 3 sizes)", "100e6 * 2e6 * 3", "B"), ("Feed reads per second", "500e6 * 20 / 86400", "/s", "20 feed loads per user per day"),
                  ("CDN egress per day (500 M users × 100 images × 200 KB)", "500e6 * 100 * 200e3", "B")]),
  SEQ("Uploading a photo", ["App", "Upload API", "S3", "Processing queue", "Media workers", "Metadata DB"],
      [["App", "Upload API", "POST /uploads → want to upload 2 MB jpeg"], ["Upload API", "App", "pre-signed S3 URL (valid 15 min)", "r", "The API server never touches the bytes, so it stays small and cheap."],
       ["App", "S3", "PUT photo (direct, resumable for video)"], ["S3", "Processing queue", "ObjectCreated event", "a"],
       ["Media workers", "Processing queue", "consume"], ["Media workers", "S3", "write 150 px, 640 px, 1080 px versions", "", "Also: strip EXIF location, moderation model, perceptual hash for duplicates."],
       ["Media workers", "Metadata DB", "post status = READY + media URLs", "", "Only now is the post visible and fanned out to followers' feeds (same as the news-feed design)."]]),
  SEQ("Viewing the feed", ["App", "Feed service", "Feed cache", "Metadata DB", "CDN"],
      [["App", "Feed service", "GET /feed"], ["Feed service", "Feed cache", "post ids for me"], ["Feed service", "Metadata DB", "hydrate (cached): caption, author, like count"],
       ["Feed service", "App", "posts with CDN URLs of the right size for this screen", "r"], ["App", "CDN", "GET image 640 px", "", "Served from the nearest edge; only a miss goes back to S3."]]),
  ER("Data model", [("posts", "sharded SQL (by user_id)", [("post_id", "Snowflake", "PK"), ("user_id", "bigint", "IDX"), ("caption", "text", ""), ("media", "json: sizes → URLs", ""), ("status", "PROCESSING/READY", "")], "Instagram famously sharded PostgreSQL with ids that embed the shard."),
                    ("likes", "Cassandra", [("post_id", "bigint", "PK"), ("user_id", "bigint", "PK"), ("created_at", "ts", "")], "Count kept separately as a sharded counter."), ("stories", "KV with TTL", [("user_id", "bigint", "PK"), ("story_id", "", "PK"), ("expires_at", "now + 24 h", "TTL")], "")]),
  TABLE("Decisions", ["Decision", "Why"], [["pre-signed direct uploads", "app servers out of the data path; scales with S3"], ["several resolutions", "phones get small images: faster and cheaper egress"],
                                          ["async processing", "upload returns quickly; heavy work retried by workers"], ["like counts as sharded counters", "a viral post gets thousands of likes per second on one row otherwise"]]))

X("chat-hld",
  P("""**What the system does.** One-to-one and group messaging with delivery ticks (sent ✓, delivered ✓✓, read), online presence, and offline delivery. Messages must arrive **in order**, **exactly once** from the user's point of view, within ~100 ms when both users are online. The core building block is a **persistent WebSocket** per online device plus a registry of which server each user is connected to."""),
  AN("A hotel switchboard: every guest who's in their room has a phone line to one operator desk (WebSocket gateway). A directory (session registry) says which desk serves which room. To deliver a message, look up the recipient's desk and forward it; if they're out, leave it in their pigeonhole (inbox) and slip a note under the door (push notification)."),
  CALC("Sizing", [("Messages per second", "m = 500e6 * 40 / 86400", "/s"), ("Peak", "m * 2.2", "/s"), ("Text per day", "500e6 * 40 * 100", "B"), ("Concurrent connections", "c = 100e6", ""), ("Gateway servers at 80k connections each", "c / 80e3", "")]),
  SEQ("Asha sends 'hi' to Ravi (both online)", ["Asha", "WS gateway A", "Chat service", "Message store", "Session registry", "WS gateway B", "Ravi"],
      [["Asha", "WS gateway A", "send {conv, clientMsgId, 'hi'}", "", "clientMsgId (a UUID made on the phone) lets the server drop duplicates if the phone retries."],
       ["WS gateway A", "Chat service", "forward"], ["Chat service", "Message store", "append (conv, seq = 1043)", "", "The service owning this conversation's partition assigns the next sequence number: that's what makes ordering reliable."],
       ["Chat service", "Asha", "ack 'sent' ✓ (seq 1043)", "r"], ["Chat service", "Session registry", "where is Ravi connected?"], ["Session registry", "Chat service", "gateway B", "r"],
       ["Chat service", "WS gateway B", "deliver (via pub/sub)", "a"], ["WS gateway B", "Ravi", "push message"], ["Ravi", "Chat service", "ack delivered ✓✓", "", "Later a 'read up to seq 1043' receipt flows back the same way."]]),
  SEQ("Ravi is offline", ["Chat service", "Session registry", "Push (APNs/FCM)", "Ravi's phone"],
      [["Chat service", "Session registry", "where is Ravi?"], ["Session registry", "Chat service", "not connected", "r"], ["Chat service", "Push (APNs/FCM)", "notification 'Asha: hi'", "a"],
       NOTE(["Chat service", "Ravi's phone"], "Ravi opens the app"), ["Ravi's phone", "Chat service", "sync: give me messages after seq 1040", "", "The client remembers the last sequence it has per conversation, so reconnect = fetch the gap, in order."]]),
  ER("Data model", [("messages", "Cassandra / ScyllaDB", [("conv_id", "uuid", "PK"), ("bucket", "month", "PK"), ("seq", "bigint", "PK"), ("msg_id", "uuid", ""), ("sender_id", "bigint", ""), ("body", "text / ciphertext", "")], "Partition = one conversation (per month), sorted by seq: 'last 50 messages' is one sequential read."),
                    ("user_inbox", "Cassandra", [("user_id", "bigint", "PK"), ("conv_id", "uuid", "PK"), ("last_read_seq", "bigint", ""), ("unread", "int", "")], "Drives the chat list and unread badges."),
                    ("sessions", "Redis", [("user_id → gateway", "string", "TTL")], "Refreshed by heartbeats; expires if the phone disappears.")]),
  TABLE("Deep-dive answers", ["Topic", "Design"], [["ordering", "per-conversation sequence assigned by one owner; clients sort by seq"], ["exactly-once (as seen by users)", "at-least-once delivery + dedupe by clientMsgId/msg_id"],
        ["group of 500", "fan-out to each member's gateway; channels with 100k members switch to pull"], ["presence", "heartbeat every 30 s refreshes a TTL key; changes published only to online friends"],
        ["end-to-end encryption", "Signal protocol on devices; the server stores and forwards ciphertext"], ["media", "upload to object storage, message carries the URL + key"]]))

X("autocomplete-hld",
  P("""**What the system does.** As you type `syst`, suggestions like *system design*, *systemd*, *system of a down* appear within ~50 ms. With billions of searches and several requests per search, that's hundreds of thousands of lookups per second, so every answer must come **from memory, precomputed**. Suggestions come from what other people searched, weighted towards recent popularity."""),
  AN("A trie is a tree of letters: s → y → s → t. If every node also keeps a sticky note with 'the 10 most popular searches below me', answering a prefix is just walking 4 steps and reading the note. No searching at query time."),
  CALC("Sizing", [("Searches per second", "s = 10e9 / 86400", "/s"), ("Suggest requests per second (6 per search after debouncing)", "s * 6", "/s"), ("Peak", "s * 6 * 1.5", "/s"),
                  ("Trie size (100 M distinct queries × ~30 B per node-path, + top-10 lists)", "100e6 * 30 * 4", "B", "fits in RAM; replicated per shard")]),
  FLOW("Trie nodes store their top-k (counts are illustrative)", [["root"], ["s"], ["sy"], ["sys"], ["syst"], ["system (top: design 9.1M, systemd 2.3M)", "systematic (0.4M)"]],
       [["root", "s"], ["s", "sy"], ["sy", "sys"], ["sys", "syst"], ["syst", "system (top: design 9.1M, systemd 2.3M)"], ["syst", "systematic (0.4M)"]],
       "Lookup is O(length of prefix): walk down, return the stored list. Building the lists is done offline."),
  SEQ("Typing 'syst'", ["Browser", "CDN", "Suggest service", "Trie shard s–t"],
      [["Browser", "Browser", "debounce 100 ms after the last keystroke", "", "Typing 'system' quickly sends 1–2 requests, not 6."], ["Browser", "CDN", "GET /suggest?q=syst", "", "Popular prefixes are cached at the edge for a few minutes."],
       ["CDN", "Suggest service", "miss"], ["Suggest service", "Trie shard s–t", "walk s→y→s→t", "", "Shards split by prefix range; each replicated for read capacity."], ["Trie shard s–t", "Suggest service", "top-10 list", "r"],
       ["Suggest service", "Browser", "suggestions (+ user's own recent searches blended in)", "r"]]),
  FLOW("Building the trie (offline + streaming)", [["db:Query logs"], ["Aggregate counts (time-decayed)", "Trending stream (last hour)"], ["Trie builder"], ["Snapshot to suggest servers"]],
       [["Query logs", "Aggregate counts (time-decayed)", "daily batch"], ["Query logs", "Trending stream (last hour)", "Kafka"], ["Aggregate counts (time-decayed)", "Trie builder"], ["Trending stream (last hour)", "Trie builder", "boost"], ["Trie builder", "Snapshot to suggest servers", "swap atomically"]]),
  TABLE("Design points", ["Question", "Answer"], [["why precompute top-k?", "a DFS under 'a' at query time would visit millions of nodes"], ["freshness", "daily rebuild + a streaming layer for breaking news"],
        ["bad suggestions", "blocklist filter during build"], ["personalisation", "merge global top-k with the user's history at serve time"]]))

X("youtube-hld",
  P("""**What the system does.** Creators upload huge raw videos; viewers anywhere stream them smoothly on any device and network. Two pipelines: **upload → transcode** (turn one raw file into many resolutions and small segments) and **playback** (adaptive streaming from a CDN). Almost all the cost is bytes: storage and, above all, **egress bandwidth**."""),
  AN("A publisher receives one manuscript and prints it as a pocket edition, a regular edition and a large-print edition, each split into short chapters. Bookshops near readers stock the popular titles. A reader on a bumpy bus (slow network) switches to the pocket edition mid-chapter without stopping."),
  CALC("Sizing", [("Raw upload per day", "r = 5e6 * 300e6", "B"), ("Views per second", "v = 1e9 / 86400", "/s"), ("Average concurrent viewers (10-min views)", "c = v * 600", ""), ("Egress bandwidth (5 Mbps each)", "c * 5e6 / 8", "B/s"),
                  ("Egress per day", "1e9 * 600 * 5e6 / 8", "B")], "Egress ≈ 375 PB/day is why everything is served from CDN edges and ISPs' caches."),
  FLOW("Upload and transcode pipeline (a DAG)", [["u:Creator"], ["Upload service"], ["db:Raw store"], ["Split into 10-s chunks"], ["Transcode 240p", "Transcode 720p", "Transcode 1080p", "Transcode 4K"], ["Package HLS/DASH + manifest"], ["x:CDN edges"]],
       [["Creator", "Upload service", "resumable chunks"], ["Upload service", "Raw store"], ["Raw store", "Split into 10-s chunks", "event"], ["Split into 10-s chunks", "Transcode 240p"], ["Split into 10-s chunks", "Transcode 720p"], ["Split into 10-s chunks", "Transcode 1080p"], ["Split into 10-s chunks", "Transcode 4K"],
        ["Transcode 720p", "Package HLS/DASH + manifest"], ["Transcode 240p", "Package HLS/DASH + manifest"], ["Transcode 1080p", "Package HLS/DASH + manifest"], ["Transcode 4K", "Package HLS/DASH + manifest"], ["Package HLS/DASH + manifest", "CDN edges", "push popular"]],
       "Chunks are transcoded in parallel on many workers, so a 1-hour video is ready in minutes instead of hours."),
  SEQ("Playback with adaptive bitrate", ["Player", "Playback API", "CDN edge", "Origin"],
      [["Player", "Playback API", "GET /watch/abc"], ["Playback API", "Player", "manifest: renditions 240p…4K, segment URLs (signed)", "r"],
       ["Player", "CDN edge", "GET 720p/seg_001.ts", "", "Start at a modest quality for a fast start."], ["CDN edge", "Origin", "miss → fetch", "", "Long-tail videos miss; popular ones are already at the edge."],
       ["CDN edge", "Player", "segment", "r"], ["Player", "Player", "measure download speed and buffer", "", "Buffer filling fast → switch up to 1080p; network drops → switch down. Each segment is independent, so switching is seamless."],
       ["Player", "CDN edge", "GET 1080p/seg_002.ts"]]),
  ER("Data", [("videos", "MySQL + Vitess (sharded)", [("video_id", "string", "PK"), ("owner_id", "bigint", "IDX"), ("title, description", "text", ""), ("status", "UPLOADING/PROCESSING/READY", ""), ("renditions", "json", "")], ""),
              ("segments", "object storage", [("{video}/{rendition}/seg_N", "2–10 s each", "")], ""), ("watch_progress", "KV", [("user_id", "", "PK"), ("video_id", "", "PK"), ("position_s", "int", "")], "Resume watching across devices.")]),
  TABLE("Cost levers", ["Lever", "Effect"], [["better codec (VP9/AV1)", "30–50% less bandwidth for the same quality"], ["storage tiers", "old, unpopular renditions to cold storage; regenerate rarely used ones"],
                                           ["edge caches inside ISPs (Netflix Open Connect)", "traffic never crosses the internet backbone"], ["per-title encoding", "cartoons need fewer bits than action films"]]))

X("dropbox-hld",
  P("""**What the system does.** Keep a folder in sync across laptop, phone and the cloud; share folders; keep old versions. The insight that makes it efficient: never move whole files. Split each file into **blocks**, identify blocks by their **hash**, and only upload or download blocks the other side doesn't already have."""),
  AN("Moving house with labelled boxes: before shipping, you check which boxes the new house already has (same label = same contents) and only ship the missing ones. A 1 GB video where you trimmed 2 seconds means shipping one or two boxes, not the whole video."),
  CALC("Sizing", [("File changes per second", "50e6 * 10 / 86400", "/s"), ("Stored data before dedup (1 B users × 2 GB used)", "1e9 * 2e9", "B"), ("4 MB blocks to track", "1e9 * 2e9 / 4e6", "")]),
  SEQ("Saving a changed file on the laptop", ["Laptop client", "Metadata service", "Block service", "Block storage (S3)", "Notification service", "Phone client"],
      [["Laptop client", "Laptop client", "split into blocks, SHA-256 each", "", "Content-defined chunking (rolling hash) keeps unchanged regions in the same blocks even if bytes were inserted earlier in the file."],
       ["Laptop client", "Metadata service", "which of [h1…h250] do you lack?"], ["Metadata service", "Laptop client", "only h17, h18", "r", "Global dedup: blocks anyone ever uploaded are already stored."],
       ["Laptop client", "Block service", "upload h17, h18"], ["Block service", "Block storage (S3)", "PUT blocks/h17, h18"],
       ["Laptop client", "Metadata service", "commit file v8 = [h1…h250], base version v7", "", "If the server's current version isn't v7 (someone else edited), the commit is rejected → client saves a 'conflicted copy'."],
       ["Metadata service", "Notification service", "namespace changed", "a"], ["Notification service", "Phone client", "wake up (long poll answered)"],
       ["Phone client", "Metadata service", "changes since cursor"], ["Phone client", "Block service", "download only h17, h18"]]),
  ER("Metadata", [("files", "sharded MySQL (by namespace)", [("namespace_id", "bigint", "PK"), ("path", "text", "PK"), ("version", "int", ""), ("block_list", "list of hashes", ""), ("updated_at", "ts", "")], ""),
                  ("blocks", "MySQL / KV", [("hash", "sha256", "PK"), ("size", "int", ""), ("storage_key", "text", ""), ("refcount", "int", "")], "refcount 0 → garbage-collected."),
                  ("journal", "MySQL", [("namespace_id", "", "PK"), ("seq", "bigint", "PK"), ("change", "json", "")], "Clients sync by asking 'changes after seq N'.")]),
  TABLE("Why each choice", ["Choice", "Benefit"], [["blocks + hashes", "delta sync, resumable uploads, dedup across users"], ["metadata separate from bytes", "fast listing/sync; S3 for cheap durable bytes"],
                                                 ["journal + cursor", "efficient incremental sync for offline devices"], ["optimistic versioning", "no locks; conflicts are rare and visible"]]))

X("proximity-hld",
  P("""**What the system does.** 'Restaurants within 2 km of me': given a location and radius, return nearby businesses ranked by distance and rating, ~20k times per second. A normal index on latitude and longitude can't answer 'near' efficiently, so we need a **spatial index**: geohash, quadtree or S2/H3 cells. Businesses rarely move, so the index can be rebuilt offline."""),
  AN("Divide the world map into squares with names, then each square into 32 smaller squares, and so on. A geohash like `tdr1v` names one ~5 km square. 'Near me' becomes 'businesses in my square and the 8 squares around it', a simple lookup by name."),
  CALC("Sizing", [("Searches per second", "q = 100e6 * 5 / 86400", "/s"), ("Peak", "20e3", "/s"), ("Business data", "200e6 * 1e3", "B", "fits on one big DB + replicas"),
                  ("Geo index (id + geohash ≈ 30 B)", "200e6 * 30", "B", "small enough for RAM on every search server")]),
  TABLE("Geohash precision vs cell size", ["Geohash length", "Cell size (approx.)", "Use for radius"], [["4", "39 km × 19.5 km", "20 km+"], ["5", "4.9 km × 4.9 km", "2–5 km"], ["6", "1.2 km × 0.6 km", "≤ 1 km"], ["7", "153 m × 153 m", "a few blocks"]]),
  FLOW("Query = my cell + its 8 neighbours", [["NW cell", "N cell", "NE cell"], ["W cell", "my cell tdr1v", "E cell"], ["SW cell", "S cell", "SE cell"]],
       [["my cell tdr1v", "N cell"], ["my cell tdr1v", "S cell"], ["my cell tdr1v", "E cell"], ["my cell tdr1v", "W cell"]],
       "Neighbours are needed because a restaurant 50 m away may sit just across a cell border."),
  SEQ("Search 'restaurants within 2 km'", ["App", "Location search", "Geo index (memory)", "Business service"],
      [["App", "Location search", "GET /search?lat=13.08&lng=80.27&r=2km&cat=restaurant"], ["Location search", "Location search", "geohash(lat, lng, precision 5) + 8 neighbours", "", "Precision picked so a cell is about as big as the radius."],
       ["Location search", "Geo index (memory)", "ids in these 9 cells (category filter)"], ["Geo index (memory)", "Location search", "~400 candidate ids", "r"],
       ["Location search", "Location search", "exact distance (haversine), keep ≤ 2 km, rank by distance × rating", "", "Cells are squares; the exact check removes corners outside the circle."],
       ["Location search", "Business service", "hydrate top 20 (cached)"], ["Location search", "App", "results", "r"]]),
  TABLE("Geohash vs quadtree vs S2/H3", ["Index", "Idea", "Strength", "Weakness"], [["Geohash", "string prefix = cell", "works in any DB with a string index", "uneven cell shapes; border neighbours needed"],
        ["Quadtree", "split a cell into 4 when it holds > K places", "adapts to density (dense cities get small cells)", "in-memory tree, rebuild on change"], ["S2 / H3", "hierarchical cells on a sphere (squares / hexagons)", "uniform, great for rings of neighbours", "library needed"]]))

X("uber-hld",
  P("""**What the system does.** Riders request a ride; the system finds the best nearby driver within seconds, tracks the trip live, prices it and charges. The defining load is **driver location updates**: millions of drivers sending GPS every few seconds. These must go to an **in-memory geo index**, never a disk database write per update."""),
  AN("A taxi company's control room with a big wall map divided into hexagons. Every few seconds each driver's pin moves to its current hexagon. When a call comes in, the dispatcher looks at the caller's hexagon and its neighbours, picks the closest free driver, and flips that driver's sign to 'busy' in one motion."),
  CALC("Sizing", [("Location updates per second", "5e6 / 4", "/s", "5 M drivers, one update every 4 s"), ("Ride requests per second", "20e6 / 86400", "/s"), ("Location stream per day (100 B each)", "5e6 / 4 * 86400 * 100", "B"),
                  ("Geo index memory (5 M drivers × 100 B)", "5e6 * 100", "B", "tiny: it's all about write rate, not size")]),
  SEQ("Request → match → accept", ["Rider", "Ride service", "Matching", "Geo index (Redis/H3)", "Driver", "Trips DB"],
      [["Rider", "Ride service", "request ride (pickup, drop, type)"], ["Ride service", "Trips DB", "INSERT trip state=REQUESTED"], ["Ride service", "Matching", "find driver"],
       ["Matching", "Geo index (Redis/H3)", "drivers in pickup cell + ring of neighbours", "", "H3 hexagon cells; the index maps cell → available driver ids, updated by the location stream with TTLs so stale drivers disappear."],
       ["Matching", "Matching", "rank by ETA (routing engine), not straight-line distance", "", "A driver 300 m away across a river can be 15 minutes away."],
       ["Matching", "Driver", "offer (15 s to accept)"], ["Driver", "Ride service", "accept"],
       ["Ride service", "Trips DB", "UPDATE drivers SET status='ON_TRIP' WHERE id=D AND status='AVAILABLE'", "", "Conditional update: if two trips race for one driver, only one update matches. The loser re-matches."],
       ["Ride service", "Rider", "driver assigned + live location over WebSocket", "r"]]),
  STATE("Trip states", [["REQUESTED"], ["MATCHING", "CANCELLED"], ["ACCEPTED"], ["IN_PROGRESS"], ["COMPLETED"], ["PAID"]],
        [["REQUESTED", "MATCHING", ""], ["MATCHING", "ACCEPTED", "driver accepts"], ["MATCHING", "CANCELLED", "no driver / timeout"], ["ACCEPTED", "CANCELLED", "cancel (fee?)"], ["ACCEPTED", "IN_PROGRESS", "pickup"], ["IN_PROGRESS", "COMPLETED", "drop-off"], ["COMPLETED", "PAID", "async charge (idempotent)"]]),
  TABLE("Deep dives", ["Topic", "Design"], [["1.25 M writes/s", "in-memory geo index sharded by city/cell; Kafka keeps the stream for ETA models and history"], ["no double assignment", "conditional state update (or one dispatcher partition per city)"],
        ["surge pricing", "stream job computes demand/supply per cell every minute → multiplier"], ["ETA", "routing engine on a road graph with live traffic (contraction hierarchies)"], ["failure isolation", "each city/region's dispatch runs independently"]]))
